package ui

const conversationPageHTML = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Fort · Conversations</title>
<link rel="icon" href="/fort-icon.png">
<style>
:root{color-scheme:dark;--bg:#0b0d0c;--panel:#111411;--raised:#171b17;--line:#293029;--muted:#8c968c;--text:#f2f5ef;--accent:#c9ff72;--accent-ink:#172006;--danger:#ff8f82;--warn:#f1ca6e}
*{box-sizing:border-box}html,body{height:100%;margin:0}body{background:var(--bg);color:var(--text);font:14px/1.45 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;overflow:hidden}
button,textarea,input,select{font:inherit}button{color:inherit}.app{height:100vh;display:grid;grid-template-columns:286px minmax(420px,1fr) 310px}
.sidebar,.today-rail{background:var(--panel);min-width:0;overflow:auto}.sidebar{border-right:1px solid var(--line);padding:18px 14px}.today-rail{border-left:1px solid var(--line);padding:20px 18px}
.brand{display:flex;align-items:center;gap:11px;padding:0 6px 20px}.brand img{width:30px;height:30px;border-radius:8px}.brand strong{font-size:17px;letter-spacing:-.02em}.brand span{display:block;color:var(--muted);font-size:11px}
.nav{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-bottom:24px}.nav button,.ghost,.project-row,.conversation-row,.target-chip{border:1px solid transparent;background:transparent;border-radius:9px;cursor:pointer}.nav button{padding:8px 9px;color:var(--muted)}.nav button.active{background:var(--raised);border-color:var(--line);color:var(--text)}
.section-title{display:flex;align-items:center;justify-content:space-between;padding:0 6px 8px;color:var(--muted);font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase}.section-title button{border:0;background:transparent;color:var(--accent);cursor:pointer;font-size:18px}
.project-row{width:100%;display:flex;justify-content:space-between;padding:7px 8px;color:var(--muted);text-align:left;min-height:36px}.project-row:hover,.project-row.active{background:var(--raised);color:var(--text)}.project-row small{color:#657065}
.folder-line{display:flex;align-items:center;gap:2px}.folder-line .project-row{flex:1}.folder-toggle{width:36px;min-height:36px;border:0;border-radius:8px;background:transparent;color:var(--muted);cursor:pointer}.folder-toggle:hover{background:var(--raised);color:var(--text)}.folder-conversations{margin:1px 0 5px 10px;padding-left:7px;border-left:1px solid var(--line)}.folder-conversations.collapsed{display:none}.folder-conversations .conversation-row{padding-left:9px}
.conversation-heading{display:flex;align-items:center;justify-content:space-between;margin:20px 5px 8px}.conversation-heading strong{font-size:12px}.primary{border:0;border-radius:9px;background:var(--accent);color:var(--accent-ink);font-weight:750;padding:8px 12px;cursor:pointer}.primary:disabled{opacity:.35;cursor:not-allowed}
.conversation-list{display:flex;flex-direction:column;gap:3px}.conversation-row{width:100%;padding:9px 10px;text-align:left}.conversation-row:hover,.conversation-row.active{background:var(--raised);border-color:var(--line)}.conversation-row strong{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:13px}.conversation-row span{display:block;color:var(--muted);font-size:11px;margin-top:2px}
.main{min-width:0;height:100vh;display:flex;flex-direction:column;background:var(--bg)}.thread-head{height:70px;flex:none;border-bottom:1px solid var(--line);padding:14px 22px;display:flex;align-items:center;justify-content:space-between}.thread-head h1{font-size:17px;letter-spacing:-.02em;margin:0}.thread-head p{margin:2px 0 0;color:var(--muted);font-size:11px}.thread-tools{display:flex;align-items:center;gap:10px}.project-select{max-width:150px;border:1px solid var(--line);border-radius:8px;background:var(--panel);color:var(--muted);padding:6px}.participant-stack{display:flex}.mini-avatar{width:28px;height:28px;border-radius:50%;border:2px solid var(--bg);margin-left:-6px;background:#283126;color:var(--accent);display:grid;place-items:center;font-size:10px;font-weight:800}
.thread{flex:1;min-height:0;overflow:auto;padding:24px max(24px,calc((100% - 760px)/2))}.empty{height:100%;display:grid;place-items:center;text-align:center;color:var(--muted)}.empty strong{display:block;color:var(--text);font-size:20px;margin-bottom:6px}.message{margin:0 0 24px;display:grid;grid-template-columns:34px 1fr;gap:11px}.avatar{width:32px;height:32px;border-radius:50%;display:grid;place-items:center;background:var(--raised);border:1px solid var(--line);color:var(--accent);font-weight:800;font-size:11px}.message.human .avatar{background:var(--accent);color:var(--accent-ink);border:0}.message-meta{display:flex;align-items:baseline;gap:8px}.message-meta strong{font-size:13px}.message-meta time{font-size:10px;color:var(--muted)}.message pre{font:inherit;white-space:pre-wrap;word-break:break-word;margin:6px 0 0;color:#dfe5dc}
.turn-targets{margin:-12px 0 22px 45px;display:flex;flex-wrap:wrap;gap:6px}.status{display:inline-flex;align-items:center;gap:5px;border:1px solid var(--line);background:var(--panel);border-radius:12px;padding:6px 8px;font-size:10px;color:var(--muted)}.status:before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor}.status.working{color:var(--accent)}.status.failed{color:var(--danger)}.status.queued{color:var(--warn)}.status button{border:0;background:none;color:inherit;padding:0 0 0 3px;cursor:pointer;text-decoration:underline}.status details{color:var(--muted)}.status summary{cursor:pointer}.status code{display:block;max-width:260px;white-space:normal;word-break:break-all;padding:5px}
.composer-wrap{flex:none;border-top:1px solid var(--line);padding:12px max(20px,calc((100% - 780px)/2)) 16px;background:rgba(11,13,12,.94)}.target-row{display:flex;align-items:center;gap:6px;overflow:auto;padding-bottom:8px}.target-row>span{font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);margin-right:2px}.target-chip{white-space:nowrap;padding:8px 10px;min-height:44px;border-color:var(--line);color:var(--muted);font-size:11px}.target-chip.selected{background:#27351c;border-color:#4a642e;color:var(--accent)}.composer{border:1px solid var(--line);background:var(--panel);border-radius:13px;padding:10px;display:flex;align-items:flex-end;gap:9px}.composer:focus-within{border-color:#566849}.composer textarea{border:0;outline:0;resize:none;min-height:44px;max-height:160px;flex:1;color:var(--text);background:transparent}.composer .primary{height:44px}
.rail-title{font-size:15px;margin:0 0 18px}.rail-section{margin:0 0 26px}.rail-section h2{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em;margin:0 0 9px}.rail-card{border:1px solid var(--line);border-radius:10px;background:var(--raised);padding:10px;margin:0 0 7px}.rail-card strong{display:block;font-size:12px}.rail-card span{display:block;color:var(--muted);font-size:10px;margin-top:3px}.rail-empty{color:#657065;font-size:12px;padding:4px 1px}
.computers{padding:28px;overflow:auto}.computer-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:12px}.computer{border:1px solid var(--line);background:var(--panel);border-radius:13px;padding:16px}.computer h3{margin:0 0 3px;font-size:15px}.computer>span{font-size:11px;color:var(--muted)}.seat-list{margin-top:14px;display:flex;flex-direction:column;gap:6px}.seat{display:flex;justify-content:space-between;font-size:11px;padding-top:6px;border-top:1px solid var(--line)}.ready{color:var(--accent)}.unavailable{color:var(--danger)}
dialog{border:1px solid var(--line);border-radius:15px;background:var(--panel);color:var(--text);width:min(500px,calc(100vw - 32px));padding:0;box-shadow:0 24px 80px #000b}dialog::backdrop{background:#000a}.dialog-body{padding:22px}.dialog-body h2{margin:0 0 4px}.dialog-body>p{color:var(--muted);margin:0 0 18px}.field{display:block;margin:0 0 14px}.field>span{display:block;color:var(--muted);font-size:11px;margin-bottom:5px}.field input,.field select{width:100%;border:1px solid var(--line);border-radius:9px;background:var(--bg);color:var(--text);padding:9px}.seat-choice{display:flex;gap:9px;align-items:flex-start;border:1px solid var(--line);border-radius:9px;padding:9px;margin-bottom:6px}.seat-choice small{display:block;color:var(--muted)}.dialog-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:18px}.ghost{padding:8px 12px;border-color:var(--line)}
.mobile-rail-button{display:none}.today-rail.sheet{display:block;position:fixed;z-index:20;right:12px;top:12px;bottom:12px;width:min(340px,calc(100vw - 24px));border:1px solid var(--line);border-radius:14px;box-shadow:0 24px 80px #000d}
@media (max-width: 1080px){.app{grid-template-columns:250px minmax(400px,1fr)}.today-rail{display:none}.mobile-rail-button{display:inline-flex}}
@media (max-width: 860px){body{overflow:auto}.app{height:auto;min-height:100vh;display:block}.sidebar{border:0;border-bottom:1px solid var(--line);padding:12px}.brand{padding-bottom:10px}.nav{margin-bottom:10px}.sidebar-projects{display:none}.conversation-heading{margin-top:10px}.conversation-list{flex-direction:row;overflow:auto;padding-bottom:4px}.conversation-row{min-width:180px}.main{height:calc(100vh - 180px);min-height:560px}.thread-head{padding:11px 14px}.thread{padding:18px 14px}.composer-wrap{padding:10px}.today-rail{display:none}.today-rail.sheet{display:block}.computers{padding:16px}}
</style>
</head>
<body>
<div class="app">
  <aside class="sidebar">
    <div class="brand"><img src="/fort-icon.png" alt=""><div><strong>Fort</strong><span>Shared conversations</span></div></div>
    <nav class="nav"><button id="nav-conversations" class="active" onclick="showView('conversations')">Conversations</button><button id="nav-computers" onclick="showView('computers')">Computers</button></nav>
    <div class="sidebar-projects"><div class="section-title"><span>Projects</span><button title="New project" onclick="newProject()">+</button></div><div id="projects"></div></div>
    <div class="conversation-heading"><strong>Conversations</strong><button class="primary" onclick="openNewConversation()">New</button></div>
    <div id="conversation-list" class="conversation-list"></div>
  </aside>
  <main id="main" class="main"><div id="thread-head" class="thread-head"></div><div id="thread" class="thread"></div><div id="composer-wrap" class="composer-wrap"></div></main>
  <aside id="today-rail" class="today-rail"><h1 id="today-title" class="rail-title">Today <button class="ghost mobile-rail-button" onclick="toggleTodaySheet()">Close</button></h1><section class="rail-section"><h2>In progress</h2><div id="in-progress"></div></section><section class="rail-section"><h2>Scheduled today</h2><div id="scheduled"></div></section></aside>
</div>
<dialog id="new-conversation-dialog"><form method="dialog" onsubmit="createConversation(event)"><div class="dialog-body"><h2>New conversation</h2><p>Choose the agents and computers that should share this thread.</p><label class="field"><span>Name</span><input id="conversation-title" required placeholder="What are you working on?"></label><label class="field"><span>Project</span><select id="conversation-project"></select></label><div class="field"><span>Agent seats</span><div id="seat-choices"></div></div><div class="dialog-actions"><button class="ghost" value="cancel">Cancel</button><button class="primary" value="default">Create conversation</button></div></div></form></dialog>
<dialog id="project-dialog"><form onsubmit="saveProject(event)"><div class="dialog-body"><h2 id="project-dialog-title">New project</h2><p>Projects keep related conversations together without sharing their transcripts.</p><label class="field"><span>Name</span><input id="project-name" required maxlength="120" placeholder="Project name"></label><div class="dialog-actions"><button type="button" class="ghost" onclick="document.getElementById('project-dialog').close()">Cancel</button><button type="submit" class="primary">Save project</button></div></div></form></dialog>
<script>
var state={projects:[],conversations:[],seats:[],today:{in_progress:[],scheduled:[]},machines:[],current:null,detail:null,project:'all',targets:new Set(),view:'conversations',events:null,composerFocusUntil:0,editingProjectID:null,expandedProjects:new Set()};
function esc(value){return String(value==null?'':value).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
async function api(path,options){var response=await fetch(path,Object.assign({headers:{'Content-Type':'application/json'}},options||{}));if(!response.ok)throw new Error((await response.text()).trim()||('Request failed '+response.status));if(response.status===204)return null;return response.json()}
function initials(name){return String(name||'?').split(/\s+/).map(function(x){return x[0]}).join('').slice(0,2).toUpperCase()}
function when(value){if(!value)return '';return new Date(value).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}
async function loadAll(){try{var zone=Intl.DateTimeFormat().resolvedOptions().timeZone;var values=await Promise.all([api('/api/projects'),api('/api/conversations'),api('/api/conversation-seats'),api('/api/today?timezone='+encodeURIComponent(zone)),api('/api/machines')]);state.projects=values[0];state.conversations=values[1];state.seats=values[2];state.today=values[3];state.machines=values[4];renderSidebar();renderToday();renderMain()}catch(error){showError(error)}}
function showError(error){var thread=document.getElementById('thread');if(thread)thread.innerHTML='<div class="empty"><div><strong>Fort could not load this view</strong>'+esc(error.message)+'</div></div>'}
function showView(view){state.view=view;document.getElementById('nav-conversations').classList.toggle('active',view==='conversations');document.getElementById('nav-computers').classList.toggle('active',view==='computers');renderMain()}
function conversationRow(c){return '<button class="conversation-row '+(state.current===c.id?'active':'')+'" onclick="openConversation(\''+esc(c.id)+'\')"><strong>'+esc(c.title)+'</strong><span>'+esc(projectName(c.project_id))+'</span></button>'}
function renderSidebar(){var projects='<button class="project-row '+(state.project==='all'?'active':'')+'" onclick="filterProject(\'all\')"><span>All conversations</span><small>'+state.conversations.length+'</small></button>';projects+='<button class="project-row '+(state.project==='inbox'?'active':'')+'" onclick="filterProject(\'inbox\')"><span>Inbox</span></button>';state.projects.forEach(function(p){var conversations=state.conversations.filter(function(c){return c.project_id===p.id});var expanded=state.expandedProjects.has(p.id);var children=conversations.map(conversationRow).join('')||'<div class="rail-empty">No conversations yet.</div>';projects+='<div class="project-folder"><div class="folder-line"><button title="Double-click to rename" class="project-row '+(state.project===p.id?'active':'')+'" onclick="filterProject(\''+esc(p.id)+'\')" ondblclick="renameProject(\''+esc(p.id)+'\',\''+esc(p.name)+'\')"><span>'+esc(p.name)+'</span><small>'+conversations.length+'</small></button><button class="folder-toggle" aria-label="'+(expanded?'Collapse ':'Expand ')+esc(p.name)+'" aria-expanded="'+(expanded?'true':'false')+'" onclick="toggleProjectFolder(\''+esc(p.id)+'\')">'+(expanded?'⌄':'›')+'</button></div><div class="folder-conversations '+(expanded?'':'collapsed')+'">'+children+'</div></div>'});document.getElementById('projects').innerHTML=projects;var scoped=state.project==='all'||state.project==='inbox';var rows=scoped?state.conversations.filter(function(c){return state.project==='all'||!c.project_id}).map(conversationRow).join(''):'';document.getElementById('conversation-list').innerHTML=scoped?(rows||'<div class="rail-empty">No conversations here yet.</div>'):''}
function projectName(id){var project=state.projects.find(function(p){return p.id===id});return project?project.name:'Inbox'}
function filterProject(id){state.project=id;if(id!=='all'&&id!=='inbox')state.expandedProjects.add(id);renderSidebar()}
function toggleProjectFolder(id){if(state.expandedProjects.has(id)){state.expandedProjects.delete(id);if(state.project===id)state.project='all'}else{state.expandedProjects.add(id);state.project=id}renderSidebar()}
function newProject(){state.editingProjectID=null;document.getElementById('project-dialog-title').textContent='New project';document.getElementById('project-name').value='';document.getElementById('project-dialog').showModal();setTimeout(function(){document.getElementById('project-name').focus()},0)}
function renameProject(id,current){state.editingProjectID=id;document.getElementById('project-dialog-title').textContent='Rename project';document.getElementById('project-name').value=current;document.getElementById('project-dialog').showModal();setTimeout(function(){document.getElementById('project-name').focus();document.getElementById('project-name').select()},0)}
async function saveProject(event){event.preventDefault();var name=document.getElementById('project-name').value.trim();if(!name)return;var path=state.editingProjectID?'/api/projects/'+encodeURIComponent(state.editingProjectID):'/api/projects';try{await api(path,{method:state.editingProjectID?'PATCH':'POST',body:JSON.stringify({name:name})});document.getElementById('project-dialog').close();await reloadLists()}catch(error){alert(error.message)}}
function openNewConversation(){var project='<option value="">Inbox</option>'+state.projects.map(function(p){return '<option value="'+esc(p.id)+'" '+(state.project===p.id?'selected':'')+'>'+esc(p.name)+'</option>'}).join('');document.getElementById('conversation-project').innerHTML=project;var grouped={};state.seats.forEach(function(s){(grouped[s.machine]||(grouped[s.machine]=[])).push(s)});var choices=Object.keys(grouped).sort().map(function(machine){return '<div class="section-title" style="margin-top:8px"><span>'+esc(machine)+'</span></div>'+grouped[machine].map(function(s){var ready=s.state==='ready';return '<label class="seat-choice" style="'+(ready?'':'opacity:.55')+'"><input type="checkbox" name="seat" value="'+esc(s.id)+'" '+(ready?'':'disabled')+'><span><strong>'+esc(s.display_name)+'</strong><small>'+esc(s.profile)+(ready?'':' · Needs setup · '+esc(s.reason||s.state))+'</small></span></label>'}).join('')}).join('');document.getElementById('seat-choices').innerHTML=choices||'<div class="rail-empty">No agent seats are reporting yet. Recheck Computers after the hub refreshes readiness.</div>';document.getElementById('conversation-title').value='';document.getElementById('new-conversation-dialog').showModal();setTimeout(function(){document.getElementById('conversation-title').focus()},0)}
async function createConversation(event){event.preventDefault();var seats=Array.from(document.querySelectorAll('input[name="seat"]:checked')).map(function(x){return x.value});if(!seats.length){alert('Choose at least one agent seat.');return}try{var detail=await api('/api/conversations',{method:'POST',body:JSON.stringify({title:document.getElementById('conversation-title').value,project_id:document.getElementById('conversation-project').value,seat_ids:seats})});document.getElementById('new-conversation-dialog').close();await reloadLists();await openConversation(detail.conversation.id)}catch(error){alert(error.message)}}
async function reloadLists(){var values=await Promise.all([api('/api/projects'),api('/api/conversations')]);state.projects=values[0];state.conversations=values[1];renderSidebar()}
async function openConversation(id){state.current=id;state.view='conversations';try{state.detail=await api('/api/conversations/'+encodeURIComponent(id));state.targets=new Set(state.detail.participants.filter(function(p){return p.state!=='removed'}).map(function(p){return p.id}));connectEvents(id);renderSidebar();renderMain();setTimeout(function(){var input=document.getElementById('message-text');if(input)input.focus()},0)}catch(error){showError(error)}}
function connectEvents(id){if(state.events)state.events.close();state.events=new EventSource('/api/conversations/'+encodeURIComponent(id)+'/events');state.events.addEventListener('conversation',function(event){if(state.current!==id)return;state.detail=JSON.parse(event.data);renderThread();refreshToday()})}
function renderMain(){var main=document.getElementById('main');if(state.view==='computers'){main.innerHTML='<div class="computers"><div style="display:flex;align-items:center;justify-content:space-between"><div><h1>Computers</h1><p style="color:var(--muted)">Execution-ready agent seats across your Fort.</p></div><button class="primary" onclick="addComputer()">Add computer</button></div><div id="computer-grid" class="computer-grid"></div></div>';renderComputers();return}main.innerHTML='<div id="thread-head" class="thread-head"></div><div id="thread" class="thread"></div><div id="composer-wrap" class="composer-wrap"></div>';renderThread()}
function renderThread(){var oldComposer=document.getElementById('message-text');var draft=oldComposer?oldComposer.value:'';var keepFocus=(oldComposer&&document.activeElement===oldComposer)||Date.now()<state.composerFocusUntil;if(!state.detail){document.getElementById('thread-head').innerHTML='<div><h1>Conversations</h1><p>One shared thread, across agents and computers.</p></div><button class="ghost mobile-rail-button" onclick="toggleTodaySheet()">Today</button>';document.getElementById('thread').innerHTML='<div class="empty"><div><strong>Start a shared conversation</strong>Select an existing conversation or create a new one.</div></div>';document.getElementById('composer-wrap').innerHTML='';return}var d=state.detail;var participants={};d.participants.forEach(function(p){participants[p.id]=p});var active=d.participants.filter(function(p){return p.state!=='removed'});state.targets=new Set(Array.from(state.targets).filter(function(id){return active.some(function(p){return p.id===id})}));var projectOptions='<option value="">Inbox</option>'+state.projects.map(function(p){return '<option value="'+esc(p.id)+'" '+(d.conversation.project_id===p.id?'selected':'')+'>'+esc(p.name)+'</option>'}).join('');document.getElementById('thread-head').innerHTML='<div><h1>'+esc(d.conversation.title)+'</h1><p>'+active.length+' active agent'+(active.length===1?'':'s')+'</p></div><div class="thread-tools"><select aria-label="Project" class="project-select" onchange="moveCurrent(this.value)">'+projectOptions+'</select><button class="ghost" onclick="addAgentToCurrent()">Add agent</button><div class="participant-stack">'+active.map(function(p){return '<span class="mini-avatar" title="'+esc(p.display_name)+'">'+esc(initials(p.display_name))+'</span>'}).join('')+'</div><button class="ghost mobile-rail-button" onclick="toggleTodaySheet()">Today</button></div>';var targetsByTurn={};d.targets.forEach(function(t){(targetsByTurn[t.turn_id]||(targetsByTurn[t.turn_id]=[])).push(t)});var messages=d.messages.map(function(m){var p=participants[m.author_id];var human=m.author_kind==='human';var name=human?'You':(p?p.display_name:'Agent');var identity=human||!p?'':('<span>'+esc(p.profile+(p.model?' · '+p.model:'')+' · '+p.machine)+'</span>');var html='<article class="message '+(human?'human':'')+'"><div class="avatar">'+esc(human?'Y':initials(name))+'</div><div><div class="message-meta"><strong>'+esc(name)+'</strong>'+identity+'<time>'+esc(when(m.created_at))+'</time></div><pre>'+esc(m.body)+'</pre></div></article>';if(human&&targetsByTurn[m.turn_id])html+=renderTargetStates(targetsByTurn[m.turn_id],participants);return html}).join('');document.getElementById('thread').setAttribute('aria-live','polite');document.getElementById('thread').innerHTML=messages||'<div class="empty"><div><strong>The thread is ready</strong>Write a message and choose who should answer.</div></div>';var chips='<button class="target-chip '+(state.targets.size===active.length&&active.length?'selected':'')+'" onclick="targetEveryone()">Everyone</button>'+active.map(function(p){return '<button class="target-chip '+(state.targets.has(p.id)?'selected':'')+'" onclick="toggleTarget(\''+esc(p.id)+'\')">'+esc(p.display_name)+'</button>'}).join('');document.getElementById('composer-wrap').innerHTML='<div class="target-row"><span>To:</span>'+chips+'</div><div class="composer"><textarea id="message-text" placeholder="Message this conversation" onkeydown="composerKey(event)"></textarea><button class="primary" onclick="sendTurn()">Send</button></div>';var newComposer=document.getElementById('message-text');newComposer.value=draft;if(keepFocus)setTimeout(function(){newComposer.focus()},0);var thread=document.getElementById('thread');thread.scrollTop=thread.scrollHeight}
async function moveCurrent(projectID){try{await api('/api/conversations/'+encodeURIComponent(state.current),{method:'PATCH',body:JSON.stringify({project_id:projectID})});state.detail.conversation.project_id=projectID;await reloadLists()}catch(error){alert(error.message)}}
async function addAgentToCurrent(){var used=new Set(state.detail.participants.filter(function(p){return p.state!=='removed'}).map(function(p){return p.seat_id}));var choices=state.seats.filter(function(s){return s.state==='ready'&&!used.has(s.id)});if(!choices.length){alert('No other ready agent seats are available.');return}var menu=choices.map(function(s,i){return (i+1)+'. '+s.display_name}).join('\n');var selected=Number(prompt('Choose an agent seat:\n\n'+menu));if(!selected||!choices[selected-1])return;try{await api('/api/conversations/'+encodeURIComponent(state.current)+'/participants',{method:'POST',body:JSON.stringify({seat_id:choices[selected-1].id})});await openConversation(state.current)}catch(error){alert(error.message)}}
function toggleTodaySheet(){document.getElementById('today-rail').classList.toggle('sheet')}
function renderTargetStates(targets,participants){return '<div class="turn-targets" aria-live="polite">'+targets.map(function(t){var p=participants[t.participant_id];var action=t.state==='failed'||t.state==='canceled'?'<button onclick="retryTarget(\''+esc(t.id)+'\')">Retry</button>':(t.state==='queued'||t.state==='working'?'<button onclick="cancelTarget(\''+esc(t.id)+'\')">Cancel</button>':'');var details='<details><summary>Details</summary><code>Run '+esc(t.run_id)+(t.error?'<br>'+esc(t.error_code||'failed')+': '+esc(t.error):'')+'</code></details>';return '<span class="status '+esc(t.state)+'">'+esc(p?p.display_name:'Agent')+' · '+esc(t.state)+action+details+'</span>'}).join('')+'</div>'}
function toggleTarget(id){state.targets.has(id)?state.targets.delete(id):state.targets.add(id);renderThread()}
function targetEveryone(){var active=state.detail.participants.filter(function(p){return p.state!=='removed'});var everyone=state.targets.size===active.length;state.targets=new Set(everyone?[]:active.map(function(p){return p.id}));renderThread()}
function composerKey(event){if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();sendTurn()}}
async function sendTurn(){var input=document.getElementById('message-text');var text=input.value.trim();if(!text||!state.targets.size)return;state.composerFocusUntil=Date.now()+5000;input.value='';try{await api('/api/conversations/'+encodeURIComponent(state.current)+'/turns',{method:'POST',body:JSON.stringify({client_turn_id:crypto.randomUUID(),text:text,participant_ids:Array.from(state.targets)})});state.detail=await api('/api/conversations/'+encodeURIComponent(state.current));renderThread();document.getElementById('message-text').focus();refreshToday()}catch(error){input.value=text;input.focus();alert(error.message)}}
async function retryTarget(id){try{await api('/api/conversations/'+encodeURIComponent(state.current)+'/targets/'+encodeURIComponent(id)+'/retry',{method:'POST',body:'{}'});state.detail=await api('/api/conversations/'+encodeURIComponent(state.current));renderThread()}catch(error){alert(error.message)}}
async function cancelTarget(id){try{await api('/api/conversations/'+encodeURIComponent(state.current)+'/targets/'+encodeURIComponent(id)+'/cancel',{method:'POST',body:'{}'});state.detail=await api('/api/conversations/'+encodeURIComponent(state.current));renderThread()}catch(error){alert(error.message)}}
function renderToday(){document.getElementById('today-title').innerHTML='Today <small style="color:var(--muted);font-weight:400">'+esc(state.today.date||'')+' '+esc(state.today.timezone_abbreviation||'')+'</small><button class="ghost mobile-rail-button" onclick="toggleTodaySheet()">Close</button>';var progress=(state.today.in_progress||[]).map(function(item){var click=item.conversation_id?' onclick="openConversation(\''+esc(item.conversation_id)+'\')"':'';return '<button style="width:100%;color:inherit;text-align:left" class="rail-card"'+click+'><strong>'+esc(item.conversation_title)+'</strong><span>'+esc(item.project_name?item.project_name+' · ':'')+esc(item.participant_name||item.agent)+' · '+esc(item.machine||'local')+' · '+esc(item.state)+'</span></button>'}).join('');document.getElementById('in-progress').innerHTML=progress||'<div class="rail-empty">Nothing in progress.</div>';var labels={scheduled:'Upcoming',running:'Running',succeeded:'Completed',failed:'Failed',canceled:'Canceled'};var scheduled=(state.today.scheduled||[]).map(function(item){return '<div class="rail-card"><strong>'+esc(item.title||item.flow_id)+'</strong><span>'+esc(when(item.scheduled_for))+' · '+esc(item.recurrence||'')+' · '+esc(labels[item.state]||item.state)+'</span></div>'}).join('');document.getElementById('scheduled').innerHTML=scheduled||'<div class="rail-empty">Nothing scheduled today.</div>'}
async function refreshToday(){try{var zone=Intl.DateTimeFormat().resolvedOptions().timeZone;state.today=await api('/api/today?timezone='+encodeURIComponent(zone));renderToday()}catch(error){}}
async function refreshInventory(){try{var values=await Promise.all([api('/api/conversation-seats'),api('/api/machines')]);state.seats=values[0];state.machines=values[1];if(state.view==='computers')renderComputers()}catch(error){}}
function renderComputers(){var byName={};state.machines.forEach(function(m){byName[m.name]={machine:m,seats:[]}});state.seats.forEach(function(s){if(!byName[s.machine])byName[s.machine]={machine:{name:s.machine,reachable:s.state==='ready'},seats:[]};byName[s.machine].seats.push(s)});var html=Object.keys(byName).sort().map(function(name){var item=byName[name];var ready=item.seats.some(function(s){return s.state==='ready'});return '<article class="computer"><h3>'+esc(name)+'</h3><span>'+(ready?'Ready to chat':(item.machine.reachable?'No ready agent seats':'Unavailable'))+'</span><div class="seat-list">'+item.seats.map(function(s){return '<div class="seat"><span>'+esc(s.display_name.replace(' on '+name,''))+'</span><span class="'+esc(s.state)+'">'+esc(s.state)+'</span></div>'}).join('')+'</div></article>'}).join('');document.getElementById('computer-grid').innerHTML=html||'<div class="rail-empty">No computers are reporting yet.</div>'}
async function addComputer(){try{var invite=await api('/api/mesh/invite',{method:'POST',body:'{}'});prompt('Run this command on the computer you want to add:',invite.join_cmd)}catch(error){alert('Run fort mesh invite on the hub, then use the join command it prints.\n\n'+error.message)}}
loadAll();setInterval(refreshToday,5000);setInterval(refreshInventory,10000);
</script>
</body>
</html>`
